// E2E-120: Choosing a section on the rail docks that section's tree, marks the rail entry current, and moves the URL to it
func TestE2E120(t *testing.T) {
	s := scenarios.New(t, "E2E-120")
	s.Given(`the workspace is connected`)
	s.And(`the Product Owner has the workspace "home" open`)
	s.When(`the Product Owner clicks rail-item[section=architecture]`)
	s.Then(`the page shows sidebar-section[section=architecture]`)
	s.And(`the page does not show sidebar-section[section=product]`)
	s.And(`rail-item[section=architecture] has attribute "aria-current" = "page"`)
	s.And(`the URL ends with "/architecture"`)
	s.And(`the route is served by an App Router module`)
	s.Done()
}

