// E2E-147: With no CLI connected a save reports the mapped failure and never claims to have saved
func TestE2E147(t *testing.T) {
	s := scenarios.New(t, "E2E-147")
	s.Given(`the workspace is connected`)
	s.And(`the Product Owner has the workspace "architecture" open`)
	s.When(`the remote is stopped`)
	s.And(`the Product Owner appends a unique comment in the editor`)
	s.Then(`the session is not listed`)
	s.And(`the write returns status 404 or 504`)
	s.And(`the response names the error its status maps to`)
	s.And(`save-state does not have attribute "data-save-state" = "saved"`)
	s.And(`no allowed document changed`)
	s.Done()
}

// E2E-148: A CLI that dies after accepting a write either completes it with a full receipt or reports the failure, and never reports a success it cannot evidence
func TestE2E148(t *testing.T) {
	s := scenarios.New(t, "E2E-148")
	s.Given(`the workspace is connected`)
	s.And(`the Product Owner has the workspace "architecture" open`)
	s.When(`the Product Owner appends a unique comment in the editor`)
	s.And(`the remote is stopped once the write is in flight`)
	s.Then(`the write returns status 200, 404 or 504`)
	s.And(`a successful write carries a receipt naming the path, the file's hash and a work id`)
	s.And(`a successful write's receipt is corroborated by the relay's audit for the same work`)
	s.And(`a failed write leaves save-state short of "saved"`)
	s.Done()
}

