// E2E-216: The empty state waits for an answer, so a list still loading never flashes that nothing is connected
func TestE2E216(t *testing.T) {
	s := scenarios.New(t, "E2E-216")
	s.Given(`the relay is running`)
	s.And(`the sessions read is held open`)
	s.When(`the Product Owner opens "/"`)
	s.Then(`the page issued a sessions read`)
	s.And(`the page shows exactly 0 sessions-empty`)
	s.And(`releasing the read with no sessions shows sessions-empty`)
	s.Done()
}

// E2E-217: The list calls itself unavailable only after failures have persisted, and returns on its own when they stop
func TestE2E217(t *testing.T) {
	s := scenarios.New(t, "E2E-217")
	s.Given(`the relay is running`)
	s.And(`a remote is running`)
	s.And(`the Product Owner has "/" open`)
	s.When(`the sessions read begins failing`)
	s.Then(`the page shows exactly 0 sessions-unavailable for the first 22 seconds`)
	s.And(`the page shows sessions-unavailable within 50 seconds`)
	s.And(`sessions-unavailable matches (?i)unavailable|unable to load`)
	s.And(`the page shows exactly 0 session-row`)
	s.And(`letting the read succeed again brings the row back and clears the notice`)
	s.Done()
}

// E2E-218: A read that hangs is a failure too, so the list is not held silent forever by a request that never answers
func TestE2E218(t *testing.T) {
	s := scenarios.New(t, "E2E-218")
	s.Given(`the relay is running`)
	s.And(`a remote is running`)
	s.And(`the Product Owner has "/" open`)
	s.When(`the sessions read begins hanging`)
	s.Then(`the page shows sessions-unavailable within 80 seconds`)
	s.And(`the page shows exactly 0 session-row`)
	s.And(`letting the read succeed again brings the row back and clears the notice`)
	s.Done()
}

// E2E-219: An answer that cannot be understood is a failure, never the honest empty state, because nothing-is-connected is a claim and not a fallback
func TestE2E219(t *testing.T) {
	s := scenarios.New(t, "E2E-219")
	s.Given(`the relay is running`)
	s.And(`the sessions read answers 200 with a body that is not a session list`)
	s.When(`the Product Owner opens "/"`)
	s.Then(`the page shows exactly 0 sessions-empty for 8 seconds`)
	s.And(`a genuine empty answer then shows sessions-empty`)
	s.Done()
}

